def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)

    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue

            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                cr, cc = stack.pop()
                component.append((cr, cc))
                for nr, nc in ((cr - 1, cc), (cr + 1, cc),
                               (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < h and 0 <= nc < w
                            and (nr, nc) not in seen
                            and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        stack.append((nr, nc))

            minr = min(x[0] for x in component)
            maxr = max(x[0] for x in component)
            minc = min(x[1] for x in component)
            maxc = max(x[1] for x in component)
            height = maxr - minr + 1
            width = maxc - minc + 1

            expected_border = {
                (rr, cc)
                for rr in range(minr, maxr + 1)
                for cc in range(minc, maxc + 1)
                if rr in (minr, maxr) or cc in (minc, maxc)
            }
            if (height < 3 or width < 3
                    or set(component) != expected_border):
                continue

            fill = 7 if height % 2 == 1 else 2
            for rr in range(minr + 1, maxr):
                for cc in range(minc + 1, maxc):
                    if grid[rr][cc] == background:
                        out[rr][cc] = fill

    return out
